  traveltrust_token_layer_governance_title: "治理层（Governance）",
  traveltrust_token_layer_governance_body:
    "TTG、Country Pool、FeeRouter 区域与 Global 分账等以 82–84 及 Runbook §7.1 为 Target/路线图；可分配费用基数与承销档位是两套数字，勿混读（84 §1.3）。",
  traveltrust_token_layer_utility_title: "旅行效用层",
  traveltrust_token_layer_utility_body:
    "积分、会员或生态效用属产品与融资沟通中的效用叙事，须在对外稿中与证券式分红区分；具体权利义务以法务定稿为准。",
  traveltrust_token_layers_note:
    "用途、锁仓、释放曲线等图表仅展示已审版本；本页不承诺持币即享固定回报。",
  traveltrust_allocation_title: "早鸟份额（Allocation）",
