  traveltrust_quickExplain_footnote:
    "产品主链口径：链下确认完成 →（若适用）评分 → 链上 release；详见 01 / 53。",
  traveltrust_problem_title: "为何需要更好的旅游金融轨道",
  traveltrust_problem_body: "跨境支付摩擦、平台经济不透明，以及行程变更或争议时救济路径不清。",
  traveltrust_solution_title: "TravelTrust 提供什么",
  traveltrust_solution_body:
    "以订单为中心的托管（Escrow）、按部署落地的向导质押与资格（Registry），以及与 82–84 文档分层的治理经济叙事——不将路线图代币与行程结算币混读。",
  traveltrust_highlights_title: "核心能力",
