  traveltrust_trust_title: "信任与事实层",
  traveltrust_trust_body:
    "当前产品切片中，订单以 EVM L2 上 allowlist 稳定币结算。标注为 Target 的能力（如 TTG、Country Pool、FeeRouter 扩展）属路线图，除非你的环境已另行部署。",
  traveltrust_trust_bullet_escrow:
    "订单资金走链上 Escrow；释放顺序遵循 01 / 53：行程完成确认、（若适用）评分与双方确认后，再链上 release。",
  traveltrust_trust_bullet_allowlist:
    "行程结算以 allowlist 稳定币为主；代币白名单与合约配置以当前部署环境为准。",
  traveltrust_trust_bullet_guide:
    "向导接单与档期占用与业务规则一致；质押与 Registry 以已部署合约为准，叙事与 81 / 08-3 分层。",
  traveltrust_trust_bullet_disputes:
    "争议路径与 01 / 03 对齐：结构化流程下人工裁决与（若配置）合约执行；入口见争议与帮助中心。",
  traveltrust_trust_bullet_target:
    "页面动画与演示数字为视觉隐喻或示例，不等同链上实时成交；DAO、区域池、费路由扩展须标注 Target 或未部署前不构成承诺（13-1 表 2-续、83 附录 I.0 口径）。",
