  traveltrust_legacy_faq_title: "常见问题",
  traveltrust_legacy_faq_intro:
    "以下为产品向说明；对外法务口径与辖区披露以 08-4 及定稿清单为准。",
  traveltrust_legacy_faq_q1: "旅游托管资金是否安全？",
  traveltrust_legacy_faq_a1:
    "在已配置部署的环境中，订单走链上 Escrow，并以 allowlist 稳定币结算；钱包由你自持，应用仅编排签名。非托管边界详见 08-4 与帮助中心。",
  traveltrust_legacy_faq_q2: "是否必须持有某种代币才能下单？",
  traveltrust_legacy_faq_a2:
    "现行产品路径以 EVM L2 上 allowlist 稳定币（如 USDC）结算。TTG、Country Pool、FeeRouter 扩展等在 82–84 中按 Target / 路线图表述，不得理解为已替代行程结算币。",
  traveltrust_legacy_faq_q3: "结算与释放如何发生？",
  traveltrust_legacy_faq_a3:
    "主链口径见 01 / 53：双边确认、托管入金、链下确认行程完成、（若适用）评分，条件满足后再链上 release；并非单一「完成」即等同放款。",
  traveltrust_legacy_faq_q4: "某条链或功能是否已上线？",
  traveltrust_legacy_faq_a4:
    "取决于你所连接的环境。请以帮助中心、网络状态与治理参数查看运行时真值；本页为叙事入口，非实时状态看板。",
  traveltrust_legacy_faq_q5: "争议如何处理？",
  traveltrust_legacy_faq_a5:
    "与 01 / 03 一致：结构化路径下，在已配置时由人工裁决后走合约执行。产品入口见 /disputes 与 /help。",
  traveltrust_legacy_faq_visual_note:
    "若后续增加动效演示，仅为视觉隐喻，不代表链上实时成交或路由真值。",
  traveltrust_settlementBody:
    "旅行订单链上托管（Escrow）在 MVP 与现行实现中以 allowlist 稳定币（如 USDC）为主要结算手段。治理代币（TTG）或 Country Pool 等叙事若为路线图或融资层内容，须标注为 Target，不得暗示已替代订单结算币。",
  traveltrust_feeRouter_section_title: "平台费路由（运维/集成）",
