  help_backHome: "返回首页",
  help_platformBullet1: "TravelTrust 帮助旅行者安全预订行程：行程费用在托管中锁定，完成履约后再释放；平台不经手、不挪用你的行程款。",
  help_platformBullet2: "多签具备 Pause/冻结能力属于运维与安全应急权限；Pause 时仅暂停链上转出，不转移资产所有权。",
  help_platformBullet3:
    "当前为混合治理阶段（多签应急、人工仲裁等能力并存）；详细规则见《服务条款》。",
  help_disputesParagraph:
    "订单争议、证据提交与仲裁流程以《服务条款》为准。系统暂停链上转出期间：通常仍可查看订单与余额、提交申诉材料；不可新建订单或完成链上转出。恢复条件与例外见服务条款。",
  help_faqTitle: "常见问题",
