  terms_title: "服务条款",
  terms_intro: "以下核心表述与 TravelTrust《对外口径包》一致。完整服务条款以法务定稿为准；文档版本与定稿日期见项目文档 08-4 文末。",
  terms_section1Title: "1. 我们是谁",
  terms_section1Bullet1: "一句话：TravelTrust 是旅行预订平台——行程费用在托管中保护至履约完成，并提供可验证信誉；平台不经手、不挪用你的行程款。",
  terms_section1Bullet2: "合同关系：游客↔向导，平台为中介。",
  terms_section1Bullet3: "当前阶段：混合治理态（多签+人工仲裁+Pause+Runbook）；非纯无许可协议。",
  terms_section2Title: "2. 资金与托管边界",
  terms_section2Bullet1: "平台不托管用户资金；资金在链上 Escrow，用户自签交易。",
  terms_section2Bullet2: "多签具备 Pause/冻结能力属于运维与安全应急权限，非对用户资金的日常控制；Pause 仅暂停链上转出、不转移资产所有权。",
  terms_footerNote: "使用 TravelTrust 即表示您同意遵守上述口径与平台规则、当地法律法规。完整条款、仲裁与争议、合规等见法务定稿版本。",
  terms_backHome: "返回首页",

  privacy_title: "隐私政策",
  privacy_intro: "以下核心表述与 TravelTrust《对外口径包》一致。完整隐私政策以法务定稿为准；文档版本与定稿日期见项目文档 08-4 文末。",
  privacy_section1Title: "1. 证据与数据保留",
  privacy_section1Bullet1: "争议相关证据：保留期届满后可删原文件；hash + receipt 永久保留，可向司法机构提供以证明「曾存在、何时、何人」；不保留可逆原文件。",
  privacy_section1Bullet2: "所收集的 DID、护照等敏感数据：加密存储、访问控制、保留期限及删除策略以法务定稿为准，并符合当地隐私法规。",
  privacy_section2Title: "2. 数据主权与跨境",
  privacy_section2Bullet1: "证据存储若跨境传输或涉及 EU 用户，须满足首发司法域与业务地数据合规（如 EU GDPR 传输限制、本地化要求）。",
  privacy_section2Bullet2: "数据主权分布、DPA（数据处理协议）、法律适用地、data controller 等以法务定稿与 Runbook 为准。",
  privacy_footerNote: "使用 TravelTrust 即表示您知悉上述口径。完整隐私政策（含被遗忘权、hash 与 GDPR 协调等）见法务定稿版本。",
  privacy_backHome: "返回首页",

